// src/lib/motion-core/image-accordion-entry.js

var ACCORDION_CSS = `
.acc-scene {
  display: grid;
  min-height: var(--motion-height, 300px);
  place-items: center;
  background: #f4f4f4;
}

.acc {
  display: flex;
  align-items: stretch;
  width: 340px;
  height: 300px;
  overflow: hidden;
  border-radius: var(--acc-radius);
  user-select: none;
  touch-action: pan-y;
}

.acc-cell {
  position: relative;
  flex-basis: 0;
  flex-shrink: 1;
  min-width: 0;
  overflow: hidden;
  border: 0;
  border-radius: var(--acc-radius);
  padding: 0;
  background: var(--muted, #ddd);
  cursor: pointer;
}

.acc-cell img {
  display: block;
  width: 100%;
  height: 100%;
  /* Constant height keeps scale stable as the cell reveals more of the image. */
  object-fit: cover;
  pointer-events: none;
  -webkit-user-drag: none;
}

.acc-cell:focus-visible {
  outline: 2px solid var(--ring, #fff);
  outline-offset: -3px;
}
`;

var DEFAULT_IMAGES = [
  { name: "樱花黄昏神社", src: "data:image/jpeg;base64," },
  { name: "雨夜末班车", src: "data:image/jpeg;base64," },
  { name: "深海巨鲸", src: "data:image/jpeg;base64," },
  { name: "天空浮岛", src: "data:image/jpeg;base64," },
  { name: "极光镜湖", src: "data:image/jpeg;base64," }
];

function mountImageAccordion(host, options = {}) {
  return createImageAccordion(host, options, ACCORDION_CSS, DEFAULT_IMAGES);
}
